Here is a C++ program that finds the nth Fibonacci number using recursion:

```c++
#include <iostream>
#include <fstream>
#include <cmath>
using namespace std;

int main() {
    // Open a file to read the first n elements of the Fibonacci sequence
    ifstream input("fibonacci.txt");
    if (input.fail()) {
        cout << "Error: unable to open the file" << endl;
        return -1;
    }
    int n;
    cin >> n; // read n
    input.close();

    // Recursive function to find the nth Fibonacci number
    int nth_fib(int n) {
        if (n <= 1) return n;
        else return nth_fib(n-1) + nth_fib(n-2);
    }

    // Write the nth Fibonacci number to the file
    ofstream output("fibonacci.txt");
    for (int i = 1; i <= n; i++) {
        output << nth_fib(i) << "\n";
    }
    output.close();

    return 0;
}
