Here is a C++ program that finds the nth number in a sequence of numbers that satisfies the conditions: `n` is the sum of the `n-1` and `n-2` numbers, and the first `n` numbers in the sequence are `0, -1, -1`:

```c++
#include <iostream>

int main() {
    // Define the sequence
    int n = 3;
    int sequence[3] = {0, -1, -1};
    // Find the nth number in the sequence
    for (int i = 0; i < n; i++) {
        sequence[i] = i + sequence[i + 1] + sequence[i + 2];
    }
    // Print the sequence
    for (int i = 0; i <= n; i++) {
        cout << sequence[i] << "\n";
    }
    return 0;
}
```</s>

